func describe(v any) string {
    switch x := v.(type) {
    case nil:
        return "ничего"
    case int, int64:
        return fmt.Sprintf("целое %v", x)   // x здесь any: несколько типов
    case string:
        return "строка длиной " + strconv.Itoa(len(x))
    case fmt.Stringer:
        return x.String()
    default:
        return fmt.Sprintf("неизвестно: %T", x)
    }
}
